"""Conventional fixedwing guidance using only own-aircraft navigation state.

PyFlyt uses an ENU world and body x forward, y left, z up. Positive pitch is
nose down; positive roll banks right. Commands address mode -1 surfaces
explicitly, avoiding the upstream mode 0 tail-surface coupling.
"""

from __future__ import annotations

from dataclasses import dataclass
import math

import numpy as np


def wrap_angle(angle: float) -> float:
    return (angle + math.pi) % (2.0 * math.pi) - math.pi


@dataclass(frozen=True)
class FlightTarget:
    heading: float
    altitude: float = 80.0
    airspeed: float = 20.0
    bank_feedforward: float = 0.0

    def __post_init__(self) -> None:
        if not all(math.isfinite(x) for x in (
            self.heading, self.altitude, self.airspeed, self.bank_feedforward
        )) or self.altitude <= 0.0 or self.airspeed <= 0.0:
            raise ValueError("flight target must be finite with positive altitude and airspeed")


@dataclass(frozen=True)
class ControlGains:
    heading_p: float = 0.8
    roll_p: float = 1.5
    roll_d: float = 0.3
    pitch_p: float = 1.5
    pitch_d: float = 0.4
    altitude_p: float = 0.3
    altitude_i: float = 0.015
    speed_p: float = 0.08
    speed_i: float = 0.015
    pitch_trim: float = -0.04
    elevator_trim: float = -0.03
    throttle_trim: float = 0.4
    altitude_throttle_p: float = 0.0
    max_vertical_speed: float | None = None
    max_bank: float = math.radians(30.0)
    max_pitch: float = math.radians(12.0)


class FixedwingAutopilot:
    """Nested PI/PD loops, shared by every prospective mission policy."""

    def __init__(self, gains: ControlGains | None = None):
        self.gains = gains or ControlGains()
        self.altitude_integral = 0.0
        self.speed_integral = 0.0

    def step(self, state: np.ndarray, target: FlightTarget, dt: float,
             measured_airspeed: float | None = None) -> np.ndarray:
        if state.shape != (4, 3) or not np.isfinite(state).all():
            raise ValueError("navigation state must be a finite (4, 3) array")
        if not math.isfinite(dt) or dt <= 0.0:
            raise ValueError("dt must be finite and positive")
        rates, attitude, velocity, position = state
        roll, pitch, heading = attitude
        g = self.gains
        speed = float(np.linalg.norm(velocity)) if measured_airspeed is None else measured_airspeed
        if not math.isfinite(speed) or speed < 0:
            raise ValueError("measured airspeed must be finite and nonnegative")
        height_error = target.altitude - position[2]
        speed_error = target.airspeed - speed
        proposed_integral = float(np.clip(self.altitude_integral + height_error * dt, -20.0, 20.0))
        proposed_vertical = g.altitude_p*height_error+g.altitude_i*proposed_integral
        saturated = (g.max_vertical_speed is not None and abs(proposed_vertical) > g.max_vertical_speed
                     and height_error*proposed_vertical > 0)
        if not saturated:
            self.altitude_integral = proposed_integral
        self.speed_integral = float(np.clip(self.speed_integral + speed_error * dt, -15.0, 15.0))
        bank = float(np.clip(
            -g.heading_p * wrap_angle(target.heading - heading) + target.bank_feedforward,
            -g.max_bank, g.max_bank,
        ))
        vertical_command = g.altitude_p*height_error+g.altitude_i*self.altitude_integral
        if g.max_vertical_speed is not None:
            vertical_command = float(np.clip(vertical_command,-g.max_vertical_speed,g.max_vertical_speed))
        pitch_target = float(np.clip(
            g.pitch_trim - math.atan2(vertical_command, max(speed, 5.0)),
            -g.max_pitch, g.max_pitch,
        ))
        aileron = float(np.clip(g.roll_p * (bank - roll) - g.roll_d * rates[0], -1.0, 1.0))
        elevator = float(np.clip(g.elevator_trim + g.pitch_p * (pitch_target - pitch) - g.pitch_d * rates[1], -1.0, 1.0))
        turn_rate = -9.81 * math.tan(bank) / max(speed, 5.0)
        rudder = float(np.clip(0.4 * (rates[2] - turn_rate * math.cos(roll)), -0.5, 0.5))
        throttle = float(np.clip(g.throttle_trim + g.speed_p * speed_error + g.speed_i * self.speed_integral
                                 + g.altitude_throttle_p * height_error, 0.0, 1.0))
        return np.array([aileron, -aileron, elevator, rudder, 0.0, throttle])


def inspection_gains():
    """Development profile with bounded vertical command and anti-windup.

    The0.8 value limits the desired vertical command, not measured climb rate.
    It requires new qualification; legacy ControlGains defaults are retained.
    """
    return ControlGains(pitch_p=4.5,elevator_trim=-.1,speed_p=.12,max_vertical_speed=.8)


def orbit_target(position: np.ndarray, center: np.ndarray, radius: float, altitude: float = 80.0,
                 airspeed: float = 20.0, direction: int = 1) -> FlightTarget:
    """Tangent vector field; direction +1 is counterclockwise in ENU."""
    if radius <= 0.0 or not math.isfinite(radius) or direction not in (-1, 1):
        raise ValueError("radius must be positive and direction must be +/-1")
    offset = position[:2] - center[:2]
    distance = float(np.linalg.norm(offset))
    radial = math.atan2(offset[1], offset[0])
    heading = radial + direction * (math.pi / 2.0 + math.atan(2.0 * (distance - radius) / radius))
    feedforward = -direction * math.atan2(airspeed ** 2, 9.81 * radius)
    return FlightTarget(heading, altitude, airspeed, feedforward)


def air_heading_for_course(course: float, wind_xy: np.ndarray, airspeed: float) -> float:
    """Crab correction from shared ideal local airdata; no mission truth input."""
    if wind_xy.shape != (2,) or not np.isfinite(wind_xy).all() or not math.isfinite(airspeed) or airspeed <= 0:
        raise ValueError("finite planar wind and positive airspeed required")
    crosswind = -wind_xy[0] * math.sin(course) + wind_xy[1] * math.cos(course)
    if abs(crosswind) >= airspeed:
        raise ValueError("requested course is infeasible in this crosswind")
    return wrap_angle(course - math.asin(crosswind / airspeed))


class SurveyRoute:
    """Counterclockwise capsule with physical semicircle transitions."""

    def __init__(self, center_y: float, half_length: float = 250.0, radius: float = 80.0):
        self.center_y, self.half_length, self.radius = center_y, half_length, radius
        self.leg = "bottom"
        self.laps = 0

    def target(self, position: np.ndarray, altitude: float) -> FlightTarget:
        x, y = position[:2]
        if self.leg == "bottom" and x >= self.half_length:
            self.leg = "right"
        elif self.leg == "right" and x <= self.half_length + 5 and y > self.center_y + 20:
            self.leg = "top"
        elif self.leg == "top" and x <= -self.half_length:
            self.leg = "left"
        elif self.leg == "left" and x >= -self.half_length - 5 and y < self.center_y - 20:
            self.leg = "bottom"
            self.laps += 1
        if self.leg in ("right", "left"):
            center = np.array([self.half_length if self.leg == "right" else -self.half_length, self.center_y])
            return orbit_target(position, center, self.radius, altitude)
        desired_y = self.center_y + (self.radius if self.leg == "top" else -self.radius)
        return FlightTarget(math.atan2(desired_y-y, -80 if self.leg == "top" else 80), altitude)

    def cross_track_error(self, position: np.ndarray) -> float:
        x, y = position[:2]
        if abs(x) <= self.half_length:
            return min(abs(y-self.center_y-self.radius), abs(y-self.center_y+self.radius))
        return abs(math.hypot(abs(x)-self.half_length, y-self.center_y)-self.radius)

"""Single job/flight-program owner. Planning never blocks the physical tick.

This is a DEVELOPMENT executor until the new mode qualification is complete.
The public actor has no reference to this object or its internal queues.
"""

from __future__ import annotations

from dataclasses import asdict, fields
import hashlib
import math
import multiprocessing as mp
import pickle
import queue
import time

import numpy as np

from envs.inspection.control import SurveyRoute, air_heading_for_course, inspection_gains, wrap_angle
from envs.inspection.guidance import LocalTrack
from envs.inspection.planning import (ObservedTrack, PlanProposal, PlanRequest, initial_program, plan)
from envs.inspection.protocol import JobBook


def program_hash(program):
    digest = hashlib.sha256()
    for path in (program.prefix,program.tail):
        digest.update(path.samples.tobytes())
        digest.update(path.wind.tobytes())
    return digest.hexdigest()


def planning_worker(requests,results):
    while True:
        request = requests.get()
        if request is None:
            return
        started = time.monotonic()
        try:
            proposal = plan(request)
        except (ValueError,ArithmeticError) as error:
            proposal = PlanProposal(request.serial,request.revision,request.commit_at,request.drone,request.tokens,
                                    None,None,None,None,str(error))
        payload = pickle.dumps((proposal,time.monotonic()-started),protocol=5)
        if len(payload) > 1100000:
            proposal = PlanProposal(request.serial,request.revision,request.commit_at,request.drone,request.tokens,
                                    None,None,None,None,"proposal exceeds bounded internal message size")
            payload = pickle.dumps((proposal,time.monotonic()-started),protocol=5)
        results.put(payload)


class FlightExecutor:
    """Three responsibilities behind one writer: jobs, local tracks, programs.

    Mission owns sensors/transport/reports. Samples accepted here carry no
    hidden identity or truth; per-aircraft local tracks are never cross-fused.
    """

    def __init__(self,homes,altitudes,wind,*,start_planner=True):
        if len(homes) != 4 or len(altitudes) != 4:
            raise ValueError("exactly four aircraft required")
        self.homes,self.home_altitudes,self.wind = tuple(homes),tuple(altitudes),tuple(wind)
        self.book = JobBook(4)
        self.programs = tuple(initial_program(float(y),self.wind) for y in homes)
        self.work_altitudes = list(altitudes)
        self.vertical_command_limit = inspection_gains().max_vertical_speed
        self.altitude_transitions = [(float(a),float(a),0.) for a in altitudes]
        self.local = [dict() for _ in homes]
        self.seen_local = [set() for _ in homes]
        self.support = [dict() for _ in homes]
        self.revision,self.serial = 0,0
        self.pending,self.ready = None,None
        self.pending_wall_deadline = None
        self.expired_serials = set()
        self.retry_after = {}
        self.refreshed_at = {}
        self.views,self.service_samples = {},{}
        self.survey_monitors = {}
        self.audit = []
        self.infrastructure_errors = []
        self.envelope_id = "development-unqualified-18m_s-0p8_vertical-command-v2"
        self.tracking = {"physics_samples":0,"max_horizontal_error_m":0.,"max_settled_altitude_error_m":0.,
                         "horizontal_tube_breach_steps":0,"altitude_envelope_breach_steps":0}
        self.context = mp.get_context("spawn")
        self.requests,self.results = self.context.Queue(maxsize=1),self.context.Queue(maxsize=1)
        self.process = None
        if start_planner:
            self.process = self.context.Process(target=planning_worker,args=(self.requests,self.results),daemon=True)
            self.process.start()

    def active(self,i):
        job = self.book.jobs.get(self.book.active.get(i))
        return job if job and job.status in ("queued","running") else None

    def tokens(self):
        return tuple((self.book.versions[i],self.book.active.get(i)) for i in range(4))

    def submit(self,drone,kind,params,expected_version,now,*,seed=None,preempt=False):
        params = dict(params)
        if seed is not None:
            if seed.arrived_at > now or seed.measured_at > seed.arrived_at:
                raise ValueError("only delivered seed may cross to another aircraft")
            params["object_type"] = seed.object_type
        response = self.book.create(drone,kind,params,expected_version,now,preempt=preempt)
        if seed is not None and response["status"] == "accepted":
            candidate = params["candidate_id"]
            if candidate not in self.local[drone]:
                self.local[drone][candidate] = LocalTrack.first(seed.estimate_xy,seed.measured_at)
                self.support[drone][candidate] = (seed.evidence_id,seed.arrived_at)
        return response

    def cancel(self,job_id,expected_version,now):
        # Logical cancellation cannot free the already committed physical path.
        return self.book.cancel(job_id,expected_version,now)

    def mark_handoff(self,destination_job,source):
        destination_job.params["handoff_from_job"] = source.job_id
        destination_job.params["handoff_from_version"] = source.version

    def local_measurement(self,obs,now):
        if (not 0 <= obs.measured_at <= now or type(obs.drone_id) is not int or not 0 <= obs.drone_id < 4):
            raise ValueError("causal local sample required")
        i,candidate = obs.drone_id,obs.candidate_id
        if obs.evidence_id in self.seen_local[i]:
            return
        self.seen_local[i].add(obs.evidence_id)
        track = self.local[i].get(candidate)
        if track is None:
            self.local[i][candidate] = LocalTrack.first(obs.estimate_xy,obs.measured_at)
        else:
            if not track.update(obs.estimate_xy,obs.measured_at):
                return
        self.support[i][candidate] = (obs.evidence_id,now)
        job = self.active(i)
        if (job is None or job.kind not in ("inspect","observe") or job.params["candidate_id"] != candidate
                or obs.measured_at <= job.created_at or obs.quality < .8 or obs.object_type != job.params.get("object_type")):
            return
        # Opportunistic views on an already committed safe continuation count;
        # actor ACK alone does not count as acquisition or service.
        if job.status == "queued":
            self.book.transition(job,"running",now,"actual local acquisition on committed flight")
        job.params.setdefault("service_started_at",obs.measured_at)
        views = self.views.setdefault(job.job_id,[])
        if not views or np.linalg.norm(np.asarray(views[0])-obs.aircraft_xy) >= 20:
            views.append(obs.aircraft_xy)
        self.service_samples.setdefault(job.job_id,[]).append(obs.measured_at)
        job.params["measurements"] = len(self.service_samples[job.job_id])
        if job.kind == "inspect" and len(views) >= 2:
            self.book.transition(job,"succeeded",now,"two actual qualified views separated by20m")
        if (job.kind == "observe" and "handoff_from_job" in job.params
                and "handoff_receiver_acquired_at" not in job.params):
            source = self.book.jobs[job.params["handoff_from_job"]]
            job.params["handoff_receiver_acquired_at"] = now
            if (source.status in ("queued","running") and self.book.active.get(source.drone_id) == source.job_id
                    and source.version == job.params["handoff_from_version"] == self.book.versions[source.drone_id]):
                self.book.transition(source,"cancelled",now,"handoff acquired actual new receiver view")
                job.params["handoff_effective_at"] = now
            else:
                job.params["handoff_source_stale_at"] = now

    def aim(self,i,now):
        job = self.active(i)
        if job is None or job.kind not in ("inspect","observe"):
            return None
        track = self.local[i].get(job.params["candidate_id"])
        return track.predict(now) if track is not None else None

    def track_age(self,i,now):
        job = self.active(i)
        track = self.local[i].get(job.params.get("candidate_id")) if job else None
        return now-track.measured_at if track is not None else math.inf

    def camera_narrow(self,i,now):
        return self.aim(i,now) is not None and self.track_age(i,now) <= 3.

    def _request(self,job,now):
        self.serial += 1
        i = job.drone_id
        estimate = None
        if job.kind in ("inspect","observe"):
            candidate = job.params["candidate_id"]
            track = self.local[i][candidate]
            evidence,available = self.support[i][candidate]
            estimate = ObservedTrack(i,track.measured_at,available,tuple(track.position),tuple(track.velocity),(evidence,))
        duration = job.params.get("duration",20.)
        if job.kind == "observe" and "service_started_at" in job.params:
            duration -= now-job.params["service_started_at"]
        region = (-300.,-100.,100.,300.)[int(job.params["region_id"].split("-")[1])] if job.kind == "survey" else None
        request = PlanRequest(self.serial,self.revision,now,now+2.,i,self.tokens(),job.kind,max(.5,duration),
                              region,estimate,self.programs,self.homes,self.wind)
        self.requests.put_nowait(request)
        row = {f.name:getattr(request,f.name) for f in fields(request) if f.name != "programs"}
        row["track"] = asdict(request.track) if request.track is not None else None
        row.update(type="plan_request",envelope_id=self.envelope_id,job_id=job.job_id)
        self.audit.append(row)
        self.pending = (request,job.job_id)
        self.pending_wall_deadline = time.monotonic()+5.

    def _altitude_interval(self,i,now):
        old,new,stamp = self.altitude_transitions[i]
        duration = abs(new-old)/self.vertical_command_limit+20.
        return (max(60.,min(old,new)-2),min(100.,max(old,new)+2)) if now-stamp < duration else (new-2,new+2)

    def _set_altitude(self,i,target,now):
        if target != self.work_altitudes[i]:
            self.altitude_transitions[i] = (self.work_altitudes[i],target,now)
            self.work_altitudes[i] = target

    def audit_tracking(self,stamp,positions):
        errors = [float(np.linalg.norm(np.asarray(pos)[:2]-p.at(stamp)[:2])) for pos,p in zip(positions,self.programs)]
        self.tracking["physics_samples"] += 1
        self.tracking["max_horizontal_error_m"] = max(self.tracking["max_horizontal_error_m"],max(errors))
        self.tracking["horizontal_tube_breach_steps"] += int(max(errors) > 6)
        altitude_bad = False
        for i,pos in enumerate(positions):
            low,high = self._altitude_interval(i,stamp)
            altitude_bad |= not low <= pos[2] <= high
            old,new,start = self.altitude_transitions[i]
            if stamp-start >= abs(new-old)/self.vertical_command_limit+20:
                self.tracking["max_settled_altitude_error_m"] = max(self.tracking["max_settled_altitude_error_m"],abs(pos[2]-self.work_altitudes[i]))
        self.tracking["altitude_envelope_breach_steps"] += int(altitude_bad)

    def _capture(self,i,now,navigation):
        sample = self.programs[i].at(now)
        state = navigation[i]
        low,high = self._altitude_interval(i,now)
        ground = sample[3]*np.array([math.cos(sample[2]),math.sin(sample[2])])
        va = float(np.linalg.norm(ground-self.wind))
        heading = air_heading_for_course(float(sample[2]),np.asarray(self.wind),va)
        metrics = {"xy_error_m":float(np.linalg.norm(state[3,:2]-sample[:2])),
                   "z_m":float(state[3,2]),"z_interval_m":[low,high],
                   "heading_error_degrees":math.degrees(abs(wrap_angle(state[1,2]-heading))),
                   "ground_speed_error_m_s":abs(float(np.linalg.norm(state[2]))-float(sample[3])),
                   "bank_error_degrees":math.degrees(abs(state[1,0]-sample[4]))}
        good = (metrics["xy_error_m"] <= 6 and low <= metrics["z_m"] <= high
                and metrics["heading_error_degrees"] <= 10 and metrics["ground_speed_error_m_s"] <= 3
                and metrics["bank_error_degrees"] <= 10)
        return good,metrics

    def _poll(self,now):
        try:
            payload = self.results.get_nowait()
        except queue.Empty:
            return
        if not isinstance(payload,bytes) or len(payload) > 1100000:
            self._planner_fault("invalid bounded planner message",now)
            return
        try:
            proposal,wall_seconds = pickle.loads(payload)
        except (pickle.PickleError,EOFError,ValueError,TypeError,AttributeError):
            self._planner_fault("malformed internal planner response",now)
            return
        if not isinstance(proposal,PlanProposal):
            self._planner_fault("wrong internal planner response type",now)
            return
        if self.pending is None or proposal.serial != self.pending[0].serial:
            if proposal.serial in self.expired_serials or self.infrastructure_errors:
                self.audit.append({"type":"late_planner_response_discarded","serial":proposal.serial,"at":now})
            else:
                self._planner_fault("planner response does not match outstanding request",now)
            return
        request,job_id = self.pending
        self.pending = None
        self.pending_wall_deadline = None
        job = self.book.jobs[job_id]
        valid = (now <= proposal.commit_at+1e-8 and proposal.revision == self.revision
                 and proposal.tokens == self.tokens() and job.status in ("queued","running"))
        self.audit.append({"type":"plan_response","serial":proposal.serial,"received_at":now,
                           "planner_wall_seconds":wall_seconds,"fresh":valid,"reason":proposal.reason,
                           "program_sha256":program_hash(proposal.program) if proposal.program else None,
                           "geometry":proposal.geometry})
        if valid and proposal.program is not None:
            self.ready = (proposal,job_id)
        else:
            self.retry_after[job_id] = now+1.

    def _planner_fault(self,reason,now):
        error = {"type":"planner_protocol_error","at":now,"reason":reason}
        self.infrastructure_errors.append(error)
        self.audit.append(error)
        self.pending,self.ready,self.pending_wall_deadline = None,None,None

    def advance(self,now,navigation,exit_dwell):
        if self.process is not None and self.process.exitcode is not None and not self.infrastructure_errors:
            self.infrastructure_errors.append({"type":"planner_process_failed","at":now,"exitcode":self.process.exitcode})
            self.audit.extend(self.infrastructure_errors)
        self._poll(now)
        if self.pending is not None:
            request,job_id = self.pending
            if now > request.commit_at and request.serial not in self.expired_serials:
                self.expired_serials.add(request.serial)
                self.audit.append({"type":"planner_capture_expired","serial":request.serial,"at":now})
            if self.pending_wall_deadline is not None and time.monotonic() > self.pending_wall_deadline:
                error = {"type":"planner_no_reply_timeout","serial":request.serial,"at":now,"wall_budget_seconds":5}
                self.infrastructure_errors.append(error)
                self.audit.append(error)
                if self.process is not None and self.process.is_alive():
                    self.process.terminate()  # no join/wait in the physical tick
                self.pending,self.pending_wall_deadline = None,None
        if self.ready is not None:
            proposal,job_id = self.ready
            if (proposal.revision != self.revision or proposal.tokens != self.tokens()
                    or self.book.jobs[job_id].status not in ("queued","running")):
                self.audit.append({"type":"proposal_invalidated","serial":proposal.serial,"at":now})
                self.ready = None
            elif now >= proposal.commit_at-1e-8:
                i = proposal.drone
                capture,metrics = self._capture(i,now,navigation)
                if not capture:
                    self.audit.append({"type":"capture_envelope_rejected","at":now,"drone":i,"serial":proposal.serial,"metrics":metrics})
                    self.retry_after[job_id] = now+1
                else:
                    programs = list(self.programs)
                    programs[i] = proposal.program
                    self.programs = tuple(programs)
                    self._set_altitude(i,96. if self.book.jobs[job_id].kind in ("inspect","observe") else self.home_altitudes[i],now)
                    self.revision += 1
                    job = self.book.jobs[job_id]
                    if job.status == "queued":
                        self.book.transition(job,"running",now,"physical program adopted")
                    job.params["planned_service_from"] = proposal.service_start
                    job.params["planned_service_until"] = proposal.service_end
                    self.refreshed_at[job_id] = now
                    if job.kind == "survey":
                        center = (-300.,-100.,100.,300.)[int(job.params["region_id"].split("-")[1])]
                        self.survey_monitors[job_id] = SurveyRoute(center)
                    self.audit.append({"type":"program_committed","serial":proposal.serial,"at":now,
                                       "revision":self.revision,"drone":i,"job_id":job_id,
                                       "program_sha256":program_hash(proposal.program)})
                self.ready = None
        for i in range(4):
            job = self.active(i)
            if job is None:
                continue
            if job.kind == "exit" and exit_dwell[i] >= 20-1e-6:
                if job.status == "queued":
                    self.book.transition(job,"running",now,"already physically in home exit")
                self.book.transition(job,"succeeded",now,"actual home-circle20s dwell")
            elif job.kind == "survey" and job.status == "running":
                start = job.params["planned_service_from"]
                if now >= start:
                    monitor = self.survey_monitors[job.job_id]
                    monitor.target(navigation[i][3],self.home_altitudes[i])
                    if "service_started_at" not in job.params and monitor.cross_track_error(navigation[i][3]) <= 6:
                        job.params["service_started_at"] = now
                    if "service_started_at" in job.params and now-job.params["service_started_at"] >= job.params["duration"]:
                        self.book.transition(job,"succeeded" if monitor.laps >= 1 else "failed",now,
                                             "actual pass and service interval" if monitor.laps >= 1 else "no complete physical pass")
            elif job.kind in ("inspect","observe"):
                if job.kind == "inspect" and now-job.created_at >= 90:
                    self.book.transition(job,"failed",now,"no qualified second view within90s")
                elif "service_started_at" not in job.params and now-job.created_at >= 90:
                    self.book.transition(job,"failed",now,"no qualified acquisition within90s")
                elif job.kind == "observe" and "service_started_at" in job.params:
                    start,duration = job.params["service_started_at"],job.params["duration"]
                    if now-start >= duration:
                        samples = self.service_samples.get(job.job_id,[])
                        ends = np.r_[np.arange(3,duration,3),duration]
                        complete = all(any(start+a < s <= start+b for s in samples) for a,b in zip(np.r_[0,ends[:-1]],ends))
                        self.book.transition(job,"succeeded" if complete else "failed",now,
                                             "local measurement bins complete" if complete else "local observation gaps retained")
            if job.status == "queued" and now-job.created_at > 90:
                self.book.transition(job,"failed",now,"finite acquisition/traffic queue timeout")
        if self.process is not None and not self.infrastructure_errors and self.pending is None and self.ready is None:
            choices = []
            for i in range(4):
                job = self.active(i)
                if job is None or self.retry_after.get(job.job_id,0) > now:
                    continue
                if (job.status == "queued" or (job.kind == "inspect" and job.job_id not in self.refreshed_at)
                        or (job.kind == "observe" and now-self.refreshed_at.get(job.job_id,-100) >= 1
                            and (job.job_id not in self.refreshed_at
                                 or now >= job.params.get("planned_service_from",now)))):
                    choices.append((0 if job.kind == "exit" else (1 if job.status == "queued" else 2),
                                    self.refreshed_at.get(job.job_id,job.created_at),i,job))
            if choices:
                try:
                    self._request(min(choices,key=lambda row:row[:3])[-1],now)
                except queue.Full:
                    pass
        targets,exits,modes = [],[],[]
        for i,p in enumerate(self.programs):
            exiting = now >= p.prefix.duration
            job = self.active(i)
            if exiting:
                self._set_altitude(i,self.home_altitudes[i],now)
            altitude = self.work_altitudes[i]
            targets.append(p.target(now,navigation[i][3],altitude))
            exits.append(exiting)
            modes.append("exit" if exiting else (job.kind if job else "continuation"))
        return targets,exits,modes

    def close(self):
        if self.process is not None:
            try:
                self.requests.put_nowait(None)
            except queue.Full:
                pass
            self.process.join(timeout=.2)
            if self.process.is_alive():
                self.process.terminate()
                self.process.join(timeout=2.)
        for q in (self.requests,self.results):
            q.cancel_join_thread()
            q.close()

"""Inspection world, causal synthetic sensing and task-tool execution.

The worker owns this object. Actor-facing RPCs expose only public_state/tool;
truth, pending packets, sensor RNG and grading remain inside the worker.
"""

from __future__ import annotations

from dataclasses import asdict, replace
import copy
import math

import numpy as np

from envs.inspection.control import FixedwingAutopilot, inspection_gains
from envs.inspection.execution import FlightExecutor
from envs.inspection.flight import FlightWorld
from envs.inspection.protocol import Evidence, Observation, ReportLedger, audit_value
from envs.inspection.scenario import CLASSES, Entity, generate_dev, in_polygon, public_card
from envs.inspection.scoring import final_static_quality, grade_dynamic_bins


class InspectionMission:
    def __init__(self, seed=0, *, reference=False, events=True, start_planner=True, wind_xy=(0.,0.)):
        self.seed, self.events = seed, events
        self.entities = generate_dev(seed, reference=reference)
        self.card = public_card()
        self.card["level"] = "L3" if events else "L2"
        self.flight = FlightWorld(seed,jitter=True,wind_xy=wind_xy)
        self.flight.controllers = [FixedwingAutopilot(inspection_gains()) for _ in range(4)]
        try:
            self.executor = FlightExecutor(self.flight.centers,self.flight.altitudes,self.flight.wind[:2],start_planner=start_planner)
        except Exception:
            self.flight.close()
            raise
        self.jobs = self.executor.book  # read view for transport/public audit; executor is the sole runtime writer
        self.modes = ["survey"]*4
        self.ledger = ReportLedger(10, set(CLASSES), self.truth_at)
        self.pending, self.delivered, self.sensor_audit = [], [], []
        self.sensor_opportunities,self.background_trials = [],[]
        self.pending_coverage, self.coverage_evidence = [], []
        self.trackers, self.covered = [{} for _ in range(4)], set()
        self.candidate_gate_multi_detection_frames = 0
        self.public_events, self.tool_audit, self.trace = [], [], []
        self.retired = set()
        self.cells = {f"cell-{x}-{y}": (float(x), float(y)) for x in range(-390, 400, 20)
                      for y in range(-390, 400, 20) if in_polygon(x, y)}
        self.entity_bodies = {}
        p = self.flight.world
        shape = p.createCollisionShape(p.GEOM_SPHERE, radius=.6)
        for entity in self.entities:
            position = entity.position(0)
            body = p.createMultiBody(baseMass=0, baseCollisionShapeIndex=shape,
                                     basePosition=[*(position or (0, 0)), .6 if position else -10])
            self.entity_bodies[entity.key] = body
        self.obstacles = []
        for x, y, half_x, half_y, height in [(-60, 20, 20, 18, 18), (210, -170, 25, 15, 22)]:
            collision = p.createCollisionShape(p.GEOM_BOX, halfExtents=[half_x, half_y, height/2])
            self.obstacles.append(p.createMultiBody(baseMass=0, baseCollisionShapeIndex=collision,
                                                    basePosition=[x, y, height/2]))
        p.register_all_new_bodies()
        p.before_physics = self._move_entities
        self.distance_m = np.zeros(4)
        self._previous_positions = np.array([s[3].copy() for s in p.all_states])
        original_audit = p.after_physics
        def audit_and_distance(stamp):
            original_audit(stamp)
            positions = np.array([p.getBasePositionAndOrientation(d.Id)[0] for d in p.drones])
            self.executor.audit_tracking(stamp,positions)
            self.distance_m += np.linalg.norm(positions-self._previous_positions, axis=1)
            self._previous_positions = positions
        p.after_physics = audit_and_distance
        self.telemetry = [None]*4
        self.job_cache = {}
        self._refresh_public()

    @property
    def t(self):
        return self.flight.t

    def truth_at(self, stamp):
        return {entity.key: position for entity in self.entities if (position := entity.position(stamp)) is not None}

    def _move_entities(self, stamp):
        for entity in self.entities:
            if entity.object_type == "dynamic":
                position = entity.position(stamp)
                self.flight.world.resetBasePositionAndOrientation(self.entity_bodies[entity.key],
                                                                  [*(position or (0, 0)), .6 if position else -10],
                                                                  [0, 0, 0, 1])

    def online(self, drone_id, stamp=None):
        stamp = self.t if stamp is None else stamp
        return not (self.events and drone_id == 1 and 210 <= stamp < 240)

    def camera_quality(self, drone_id, stamp=None):
        stamp = self.t if stamp is None else stamp
        return .55 if self.events and drone_id == 2 and 300 <= stamp < 345 else 1.0

    def _events(self):
        if self.events and self.t >= 180 and self.card["task_card_version"] == 1:
            self.card["task_card_version"], self.card["effective_from"] = 2, 180.0
            for rule in self.card["rules"]:
                if rule["rule_id"] == "static-0":
                    rule["priority"] = 3
                elif rule["rule_id"] == "dynamic-inspection":
                    rule["priority"] = 2
            self.public_events.append({"t": 180.0, "type": "priority_update", "task_card_version": 2})
        if self.events and self.t >= 360 and 3 not in self.retired:
            self.retired.add(3)
            self.executor.submit(3, "exit", {"origin": "exogenous_capacity_exit", "rule_id": None,
                                         "task_card_version": self.card["task_card_version"]},
                             self.jobs.versions[3], self.t, preempt=True)
            self.public_events.append({"t": self.t, "type": "exogenous_capacity_exit", "drone_id": 3})

    def _active(self, drone_id):
        return self.executor.active(drone_id)

    def _advance_jobs(self):
        targets,exits,self.modes = self.executor.advance(self.t,self.flight.world.all_states,self.flight.exit_dwell)
        return targets,exits

    def _visible(self, position, ground, axis, half_angle, body=None):
        target_z = .6 if body is not None else .01
        dx,dy,dz = float(ground[0])-float(position[0]),float(ground[1])-float(position[1]),target_z-float(position[2])
        distance = math.sqrt(dx*dx+dy*dy+dz*dz)
        if distance == 0 or dz >= 0:
            return False
        projection = dx*float(axis[0])+dy*float(axis[1])+dz*float(axis[2])
        if -dz < math.cos(math.radians(50))*distance or projection < math.cos(half_angle)*distance:
            return False
        hit = self.flight.world.rayTest(position.tolist(), [ground[0],ground[1],target_z])[0]
        # A ground-cell ray must be clear until its endpoint. Entity rays may
        # hit the proxy itself, but never an intervening building/other proxy.
        return hit[0] == body if body is not None else hit[0] < 0 or hit[2] >= .999

    def camera_origin(self, drone_id):
        drone = self.flight.world.drones[drone_id]
        position, quaternion = self.flight.world.getBasePositionAndOrientation(drone.Id)
        rotation = np.array(self.flight.world.getMatrixFromQuaternion(quaternion)).reshape(3, 3)
        return np.array(position)+rotation@np.array([0.0, 0.0, -.3])

    def _candidate(self, xy, object_type, stamp, drone_id, exclude=None):
        tracker = self.trackers[drone_id]
        nearby = [(math.dist(xy, c["xy"]), key) for key, c in tracker.items()
                  if key != exclude and c["object_type"] == object_type and math.dist(xy, c["xy"]) <= 25]
        key = min(nearby)[1] if nearby else f"candidate-{drone_id}-{len(tracker)+1:05d}"
        tracker[key] = {"xy": tuple(xy), "object_type": object_type, "measured_at": stamp}
        return key

    def _sample(self):
        stamp = self.t
        tick = round(stamp*2)
        local_frame = []
        for drone_id in range(4):
            if self.flight.exit_active[drone_id]:
                continue
            aircraft_position = self.flight.world.state(drone_id)[3].copy()
            position = self.camera_origin(drone_id)
            job = self._active(drone_id)
            aim = self.executor.aim(drone_id,stamp)
            tracking = aim is not None
            narrow = self.executor.camera_narrow(drone_id,stamp)
            axis = np.array([aim[0]-position[0],aim[1]-position[1],-position[2]]) if narrow else np.array([0.,0.,-1.])
            axis /= np.linalg.norm(axis)
            half_angle = math.radians(10 if narrow else 55)
            quality = self.camera_quality(drone_id)
            coverage_cells = []
            if quality >= .8:
                for cell_id,ground in self.cells.items():
                    if (math.dist(position[:2],ground) <= 150
                            and self._image_quality(position,ground,drone_id,narrow) >= .8
                            and self._visible(position,ground,axis,half_angle)):
                        coverage_cells.append(cell_id)
            self.pending_coverage.append((stamp+.5,drone_id,stamp,coverage_cells))
            # Mint the actual frame first. Association below reads only its
            # observable estimates/types, including background false detections.
            raw = []
            for index,entity in enumerate(self.entities):
                truth = entity.position(stamp)
                if truth is None or not self._visible(position,truth,axis,half_angle,self.entity_bodies[entity.key]):
                    continue
                rng = np.random.default_rng(np.random.SeedSequence([self.seed,tick,drone_id,index,0]))
                missed = bool(rng.random() < .1)
                opportunity = {"t":stamp,"drone_id":drone_id,"entity_key":entity.key,"true_class":entity.true_class,
                               "mode":"inspect" if narrow else "survey","missed":missed,"emitted_evidence_id":None}
                self.sensor_opportunities.append(opportunity)
                if missed:
                    continue
                sigma = (1. if narrow else 4.)*(1 if quality >= .8 else 3)
                estimate = tuple((np.array(truth)+rng.normal(0,sigma,2)).tolist())
                accuracy = (.99 if narrow else .8) if quality >= .8 else .65
                alternatives = [c for c in CLASSES[:3] if c != entity.true_class]
                predicted = entity.true_class if rng.random() < accuracy else str(rng.choice(alternatives))
                if entity.true_class == "normal" and not narrow:
                    predicted = "normal" if rng.random() >= .3 else str(rng.choice(CLASSES[:3]))
                raw.append({"estimate":estimate,"object_type":entity.object_type,"predicted":predicted,"sigma":sigma,
                            "image_ground":truth,"truth_xy":truth,"entity_key":entity.key,"true_class":entity.true_class,
                            "opportunity":opportunity})
            if not narrow:
                rng = np.random.default_rng(np.random.SeedSequence([self.seed,tick,drone_id,0,1]))
                triggered = bool(rng.random() < .01)
                trial = {"t":stamp,"drone_id":drone_id,"triggered":triggered,"emitted_evidence_id":None}
                self.background_trials.append(trial)
                if triggered:
                    xy = tuple((position[:2]+rng.uniform(-30,30,2)).tolist())
                    if self._visible(position,xy,axis,half_angle):
                        raw.append({"estimate":xy,"object_type":"static","predicted":str(rng.choice(CLASSES[:3])),
                                    "sigma":4.,"image_ground":xy,"truth_xy":None,"entity_key":None,"true_class":"background",
                                    "opportunity":trial})
            selected = None
            target_candidate = job.params["candidate_id"] if tracking else None
            if tracking:
                age = self.executor.track_age(drone_id,stamp)
                gate = 25.+min(50.,4.*max(0.,age-3.))
                eligible = [(math.dist(row["estimate"],aim),*row["estimate"],index)
                            for index,row in enumerate(raw) if row["object_type"] == job.params["object_type"]
                            and math.dist(row["estimate"],aim) <= gate]
                self.candidate_gate_multi_detection_frames += int(len(eligible) > 1)
                selected = min(eligible)[-1] if eligible else None
            local_index = 0
            for index,row in enumerate(raw):
                matched = index == selected
                if narrow and not matched:
                    continue
                if matched:
                    candidate = target_candidate
                    self.trackers[drone_id][candidate] = {"xy":row["estimate"],"object_type":row["object_type"],"measured_at":stamp}
                else:
                    candidate = self._candidate(row["estimate"],row["object_type"],stamp,drone_id,exclude=target_candidate)
                evidence_id = f"obs-{drone_id}-{tick}-{local_index}"
                local_index += 1
                row["opportunity"]["emitted_evidence_id"] = evidence_id
                image_quality = self._image_quality(position,row["image_ground"],drone_id,narrow)
                obs = Observation(evidence_id,candidate,drone_id,stamp,stamp+.5,row["estimate"],row["predicted"],
                                  row["object_type"],image_quality,(row["sigma"]**2,row["sigma"]**2),
                                  "inspect" if narrow else "survey",tuple(aircraft_position[:2]),tuple(position))
                route = job.params.get("report_id") if matched and job.kind == "observe" else None
                self.pending.append((stamp+.5,Evidence(obs,row["entity_key"]),route))
                local_frame.append(obs)
                self.sensor_audit.append({"evidence_id":evidence_id,"entity_key":row["entity_key"],"t":stamp,
                    "drone_id":drone_id,"mode":obs.sensor_mode,"truth_xy":row["truth_xy"],"estimate_xy":row["estimate"],
                    "predicted_class":row["predicted"],"true_class":row["true_class"],"quality":obs.quality})
        # All four cameras expose before same-frame handoff postconditions can
        # cancel the source. Original acquisition-time upload routes stay sealed.
        for obs in local_frame:
            self.executor.local_measurement(obs,stamp)

    def _image_quality(self, position, ground, drone_id, inspect):
        angle = math.degrees(math.atan2(math.dist(position[:2], ground), position[2]))
        return self.camera_quality(drone_id)*(.95 if inspect else .95-.2*(angle/50)**2)

    def _deliver(self):
        remaining = []
        for ready_at, evidence, report_id in self.pending:
            obs = evidence.observation
            if ready_at > self.t or not self.online(obs.drone_id):
                remaining.append((ready_at, evidence, report_id))
                continue
            obs = replace(obs, arrived_at=self.t)
            self.ledger.register(Evidence(obs, evidence.entity_key))
            self.delivered.append(obs)
            if report_id is not None:
                self.ledger.submit(self.report_request(obs, report_id), self.t)
        self.pending = remaining
        remaining_coverage = []
        for ready_at, drone_id, stamp, cells in self.pending_coverage:
            if ready_at > self.t or not self.online(drone_id):
                remaining_coverage.append((ready_at, drone_id, stamp, cells))
            else:
                self.covered.update(cells)
                self.coverage_evidence.append({"drone_id": drone_id, "measured_at": stamp,
                                               "arrived_at": self.t, "cells": cells})
        self.pending_coverage = remaining_coverage

    @staticmethod
    def report_request(obs, report_id):
        return {"report_id": report_id, "object_type": obs.object_type, "candidate_id": obs.candidate_id,
                "measured_at": obs.measured_at, "estimate_xy": obs.estimate_xy,
                "claimed_class": obs.estimated_class, "evidence_ids": [obs.evidence_id]}

    def _refresh_public(self):
        for i in range(4):
            if self.online(i):
                self.telemetry[i] = {"drone_id": i, "measured_at": self.t,
                                     "position": self.flight.world.state(i)[3].tolist(),
                                     "camera_quality": self.camera_quality(i), "retired": i in self.retired,
                                     "remaining_range_m": self.card["range_budget_m_per_aircraft"]-self.distance_m[i],
                                     "job_version": self.jobs.versions[i]}
        for job in self.jobs.jobs.values():
            if self.online(job.drone_id):
                safe = asdict(job)
                safe["params"] = {k: v for k, v in safe["params"].items() if k != "aim_xy"}
                self.job_cache[job.job_id] = safe

    def step(self):
        self._events()
        targets,exits = self._advance_jobs()
        self.flight.step(targets,exit_flags=exits)
        self._events()  # apply an event at this exact tick before sensing/publication
        if self.flight.world.physics_steps % 120 == 0:
            self._sample()
            self._deliver()
            self._refresh_public()
        if self.flight.world.physics_steps % 24 == 0:
            self.trace.append({"t": self.t, "positions": [s[3].tolist() for s in self.flight.world.all_states],
                               "modes": self.modes.copy(), "coverage_cells": len(self.covered),
                               "exit_dwell": self.flight.exit_dwell.tolist()})

    def public_state(self, since=0.0):
        return copy.deepcopy({"sim_time": self.t, "task_card": self.card,
                "aircraft": [{**row, "link_available": self.online(i)} for i, row in enumerate(self.telemetry)],
                "jobs": list(self.job_cache.values()), "events": self.public_events,
                "coverage": {"qualified_cells": len(self.covered), "required_cells": len(self.cells)},
                "observations": [o.public() for o in self.delivered if o.arrived_at > since],
                "report_slots_used": len(self.ledger.reports)})

    def tool(self, name, args):
        return self._tool(name,args,record=True)

    def _tool(self,name,args,*,record):
        try:
            if name == "submit_or_revise_report":
                response = self.ledger.submit(args, self.t)
            elif name == "cancel_job":
                if set(args) != {"job_id", "expected_version"}:
                    raise ValueError("tool schema fields do not match")
                existing = self.jobs.jobs.get(args["job_id"])
                if existing is not None and not self.online(existing.drone_id):
                    raise ValueError("link unavailable")
                response = self.executor.cancel(args["job_id"], args["expected_version"], self.t)
            elif name == "handoff_observation":
                required = {"from_drone", "to_drone", "candidate_id", "duration", "report_id",
                            "expected_from_version", "expected_to_version", "rule_id", "task_card_version"}
                if set(args) != required:
                    raise ValueError("tool schema fields do not match")
                source_id, destination_id = args["from_drone"], args["to_drone"]
                if (any(isinstance(i, bool) or not isinstance(i, int) or not 0 <= i < 4 for i in (source_id, destination_id))
                        or source_id == destination_id or not self.online(source_id)):
                    raise ValueError("distinct connected source and destination required")
                source = self._active(source_id)
                if (source is None or source.kind != "observe" or source.params["candidate_id"] != args["candidate_id"]
                        or args["expected_from_version"] != self.jobs.versions[source_id]
                        or isinstance(args["expected_from_version"], bool) or not isinstance(args["expected_from_version"], int)):
                    raise ValueError("source observation or version is invalid")
                forwarded = {"drone_id": destination_id, "candidate_id": args["candidate_id"], "duration": args["duration"],
                             "report_id": args["report_id"], "expected_version": args["expected_to_version"],
                             "rule_id": args["rule_id"], "task_card_version": args["task_card_version"]}
                response = self._tool("observe_track",forwarded,record=False)
                if response["status"] == "accepted":
                    self.executor.mark_handoff(self.jobs.jobs[response["job_id"]],source)
            elif name in ("assign_survey", "inspect_candidate", "observe_track", "enter_safe_exit"):
                schemas = {"assign_survey": {"drone_id", "region_id", "duration", "expected_version", "rule_id", "task_card_version"},
                           "inspect_candidate": {"drone_id", "candidate_id", "expected_version", "rule_id", "task_card_version"},
                           "observe_track": {"drone_id", "candidate_id", "duration", "report_id", "expected_version", "rule_id", "task_card_version"},
                           "enter_safe_exit": {"drone_id", "expected_version"}}
                if set(args) != schemas[name]:
                    raise ValueError("tool schema fields do not match")
                i = args["drone_id"]
                if isinstance(i, bool) or not isinstance(i, int) or not 0 <= i < 4:
                    raise ValueError("unknown aircraft")
                if not self.online(i):
                    raise ValueError("link unavailable")
                if i in self.retired and name != "enter_safe_exit":
                    raise ValueError("aircraft externally retired")
                if name != "enter_safe_exit" and (isinstance(args["task_card_version"], bool) or not isinstance(args["task_card_version"], int)
                                                  or args["task_card_version"] != self.card["task_card_version"]
                                                  or args["rule_id"] not in {r["rule_id"] for r in self.card["rules"]}):
                    raise ValueError("stale task card or unknown rule")
                params = {k: v for k, v in args.items() if k not in ("drone_id", "expected_version")}
                kind = {"assign_survey": "survey", "inspect_candidate": "inspect", "observe_track": "observe", "enter_safe_exit": "exit"}[name]
                if "duration" in params and (isinstance(params["duration"], bool) or not isinstance(params["duration"], (int, float))
                                              or not math.isfinite(params["duration"]) or params["duration"] <= 0):
                    raise ValueError("positive finite duration required")
                if "duration" in params and params["duration"] > 600-self.t:
                    raise ValueError("duration exceeds remaining mission deadline")
                if kind == "survey" and args["region_id"] not in {f"stripe-{j}" for j in range(4)}:
                    raise ValueError("unknown public region")
                seed = None
                if kind in ("inspect", "observe"):
                    visible = [o for o in self.delivered if o.candidate_id == args["candidate_id"]]
                    if not visible:
                        raise ValueError("unknown observed candidate")
                    seed = visible[-1]
                    if kind == "observe" and args["report_id"] not in self.ledger.reports:
                        raise ValueError("observation upload needs an existing report")
                response = self.executor.submit(i,kind,params,args["expected_version"],self.t,seed=seed,preempt=kind == "exit")
            else:
                response = {"status": "rejected", "reason": "tool is not in the actor allowlist"}
        except (KeyError, ValueError, TypeError) as error:
            response = {"status": "rejected", "reason": str(error)}
        if record:
            self.tool_audit.append(audit_value({"t": self.t, "name": name, "args": args, "response": response}))
        return response

    def weight(self, entity, stamp):
        return 3 if self.events and stamp >= 180 and entity.rule_id == "static-0" else (
            2 if self.events and stamp >= 180 and entity.rule_id == "dynamic-inspection" else 1)

    def grade(self):
        static, dynamic = [], []
        for entity in self.entities:
            if not entity.rule_id:
                continue
            report = next((r for r in self.ledger.reports.values() if r.associated_key == entity.key and not r.withdrawn
                           and r.object_type == entity.object_type), None)
            versions = report.versions if report else []
            if entity.object_type == "static":
                value = final_static_quality(versions, entity.origin_xy, entity.true_class, 600)
                static.append({"entity_key": entity.key, "weight": self.weight(entity, 600), "quality": value})
            else:
                value, bins = grade_dynamic_bins(versions, entity.position, entity.true_class, entity.appeared_at, 600,
                                                 weight_at=lambda t, e=entity: self.weight(e, t))
                observed, _ = grade_dynamic_bins(versions, entity.position, entity.true_class, entity.appeared_at, 600,
                                                 weight_at=lambda t, e=entity: self.weight(e, t), track="observed")
                dynamic.append({"entity_key": entity.key, "quality": value, "observed": observed,
                                "bins": [asdict(b) for b in bins]})
        c = len(self.covered)/len(self.cells)
        s = sum(x["quality"]*x["weight"] for x in static)/sum(x["weight"] for x in static)
        dynamic_denominator = sum(b["weight"] for x in dynamic for b in x["bins"])
        d = sum(b["weight"]*b["quality"] for x in dynamic for b in x["bins"])/dynamic_denominator
        q = (c+s+d)/3
        h = int(not self.flight.violations)
        remaining_range = self.card["range_budget_m_per_aircraft"]-self.distance_m
        e = int(all(x >= 20-1e-6 for x in self.flight.exit_dwell)
                and all(x >= self.card["exit_range_reserve_m"] for x in remaining_range))
        return {"C": c, "S": s, "D": d, "Q": q, "H": h, "E": e, "Y": h*e*q,
                "SR": int(h == 1 and e == 1 and c >= .8 and s >= .6 and d >= .5),
                "remaining_range_m": remaining_range.tolist(),
                "static_recall": sum(x["quality"] > 0 for x in static)/len(static),
                "static_denominator_weight": sum(x["weight"] for x in static),
                "dynamic_denominator_weight": dynamic_denominator,
                "static_entities": static, "dynamic_entities": dynamic,
                "association_ambiguities": self.ledger.association_ambiguities}

    def audit(self):
        return {"score": self.grade(), **self.business_audit()}

    def business_audit(self):
        return {"safety": self.flight.summary(), "trace": self.trace,
                "coverage_evidence": self.coverage_evidence, "required_cells": self.cells,
                "sensor_audit": self.sensor_audit, "delivered_observations": [o.public() for o in self.delivered],
                "sensor_opportunities":self.sensor_opportunities,"background_trials":self.background_trials,
                "jobs": self.jobs.public(), "job_transitions": self.jobs.transitions,
                "tool_calls": self.tool_audit, "reports": self.ledger.audit,
                "hidden_entities": [asdict(e) for e in self.entities], "public_events": self.public_events,
                "execution_audit":self.executor.audit,"development_envelope_id":self.executor.envelope_id,
                "execution_infrastructure_errors":self.executor.infrastructure_errors,
                "execution_tracking_240hz":self.executor.tracking,
                "candidate_gate_multi_detection_frames":self.candidate_gate_multi_detection_frames,
                "tool_journal_version":"top-level-v2"}

    def close(self):
        try:
            self.executor.close()
        finally:
            self.flight.close()

"""Finite analytic forward paths, usable in a planning process without PyFlyt.

No mission, generator, evidence or grader imports. Geometry is not a physical
certificate: measured tracking tubes must be supplied by qualification.
"""

from __future__ import annotations

from dataclasses import dataclass
import math

import numpy as np

from envs.inspection.control import FlightTarget, wrap_angle


@dataclass(frozen=True)
class Pose:
    x: float
    y: float
    heading: float

    def __post_init__(self):
        if not all(math.isfinite(x) for x in (self.x, self.y, self.heading)):
            raise ValueError("finite pose required")


@dataclass(frozen=True)
class Primitive:
    start: Pose
    length: float
    curvature: float

    def __post_init__(self):
        if not all(math.isfinite(x) for x in (*self.start.__dict__.values(), self.length, self.curvature)) or self.length < 0:
            raise ValueError("finite forward primitive required")

    def pose(self, distance):
        if not math.isfinite(distance) or not -1e-8 <= distance <= self.length+1e-8:
            raise ValueError("distance outside primitive")
        s = max(0., min(self.length, distance))
        p, k = self.start, self.curvature
        h = p.heading+k*s
        if abs(k) < 1e-12:
            return Pose(p.x+s*math.cos(h), p.y+s*math.sin(h), h)
        return Pose(p.x+(math.sin(h)-math.sin(p.heading))/k,
                    p.y+(-math.cos(h)+math.cos(p.heading))/k, h)

    @property
    def end(self):
        return self.pose(self.length)


def primitives(start, pieces):
    result = []
    for curvature, length in pieces:
        if length < 1e-8:
            continue
        result.append(Primitive(start, length, curvature))
        start = result[-1].end
    return tuple(result)


def stripe_transfer(start, destination_y, radius=100.):
    """Two quarter arcs; start must be an eastbound bottom-leg port.

    destination_y is the bottom-leg coordinate, not the stripe center.
    """
    if abs(wrap_angle(start.heading)) > 1e-6 or abs(destination_y-start.y) < 2*radius-1e-8 or radius <= 0:
        raise ValueError("eastbound port and sufficient lateral displacement required")
    sign = math.copysign(1., destination_y-start.y)
    return primitives(start, [(sign/radius, math.pi*radius/2),
                              (0., abs(destination_y-start.y)-2*radius),
                              (-sign/radius, math.pi*radius/2)])


def csc_connectors(start, finish, radius=100.):
    """All four forward circle-straight-circle common-tangent candidates.

    This finite set does not claim to cover every Dubins shortest path.
    Includes longer turns up to2pi, excludes infeasible internal tangents.
    """
    if not math.isfinite(radius) or radius <= 0:
        raise ValueError("positive finite radius required")
    left = lambda h: np.array([-math.sin(h), math.cos(h)])
    candidates = []
    for first in (-1, 1):
        for last in (-1, 1):
            c0 = np.array([start.x, start.y])+first*radius*left(start.heading)
            c1 = np.array([finish.x, finish.y])+last*radius*left(finish.heading)
            delta = c1-c0
            distance = float(np.linalg.norm(delta))
            shift = (first-last)*radius
            if distance < abs(shift)+1e-8 or distance < 1e-8:
                continue
            heading = math.atan2(delta[1], delta[0])+math.asin(shift/distance)
            angle0 = (first*(heading-start.heading)) % (2*math.pi)
            angle1 = (last*(finish.heading-heading)) % (2*math.pi)
            path = primitives(start, [(first/radius, radius*angle0),
                                      (0., math.sqrt(max(0., distance*distance-shift*shift))),
                                      (last/radius, radius*angle1)])
            if not path or math.dist((path[-1].end.x, path[-1].end.y), (finish.x, finish.y)) > 1e-6:
                raise ArithmeticError("connector endpoint derivation failed")
            candidates.append(path)
    return tuple(sorted(candidates, key=lambda p: sum(s.length for s in p)))


def capsule_from_bottom(start, center_y, *, half_length=250., radius=80., laps=1):
    if abs(wrap_angle(start.heading)) > 1e-6 or abs(start.y-(center_y-radius)) > 1e-6 or not -half_length-1e-6 <= start.x <= half_length:
        raise ValueError("capsule entry must lie on its eastbound bottom leg")
    if laps < 1 or isinstance(laps, bool) or not isinstance(laps, int):
        raise ValueError("positive integer laps required")
    pieces = [(0., half_length-start.x), (1/radius, math.pi*radius),
              (0., 2*half_length), (1/radius, math.pi*radius), (0., start.x+half_length)]*laps
    return primitives(start, pieces)


def course_kinematics(course, curvature, wind, airspeed):
    tangent = np.array([math.cos(course), math.sin(course)])
    normal = np.array([-tangent[1], tangent[0]])
    parallel, cross = float(wind@tangent), float(wind@normal)
    if abs(cross) >= airspeed:
        raise ValueError("path infeasible in crosswind")
    q = math.sqrt(airspeed*airspeed-cross*cross)
    ground_speed = parallel+q
    if ground_speed <= 0:
        raise ValueError("path cannot progress forward")
    derivative = cross*(1+parallel/q)
    acceleration = derivative*curvature*ground_speed*tangent+ground_speed**2*curvature*normal
    air_velocity = ground_speed*tangent-wind
    yaw_rate = float(air_velocity[0]*acceleration[1]-air_velocity[1]*acceleration[0])/(airspeed*airspeed)
    return ground_speed, -math.atan(airspeed*yaw_rate/9.81)


class TimedPath:
    """Bounded time sampling done by the planner; tick lookup is O(log N).

    The follower controls longitudinal phase as well as cross-track error.
    Sample timing is a numerical prediction, not a promise of tracking error.
    """

    def __init__(self, path, wind=(0., 0.), airspeed=20., dt=.05):
        if (not path or len(path) > 64 or not math.isfinite(dt) or dt <= 0
                or not math.isfinite(airspeed) or airspeed <= 0 or sum(p.length for p in path) <= 0):
            raise ValueError("bounded nonempty path and positive time/speed required")
        for a,b in zip(path,path[1:]):
            if (math.dist((a.end.x,a.end.y),(b.start.x,b.start.y)) > 1e-7
                    or abs(wrap_angle(a.end.heading-b.start.heading)) > 1e-7):
                raise ValueError("adjacent primitives must be spatially and tangentially continuous")
        self.path = tuple(path)
        self.wind = np.array(wind, dtype=float)
        if self.wind.shape != (2,) or not np.isfinite(self.wind).all():
            raise ValueError("finite planar wind required")
        self.airspeed = airspeed
        rows, stamp = [], 0.
        for primitive in self.path:
            distance = 0.
            while distance < primitive.length-1e-9:
                pose = primitive.pose(distance)
                speed, bank = course_kinematics(pose.heading, primitive.curvature, self.wind, airspeed)
                rows.append((stamp, pose.x, pose.y, pose.heading, speed, bank))
                step = min(dt, (primitive.length-distance)/speed)
                # Midpoint quadrature for changing wind projection on arcs.
                midpoint = primitive.pose(min(primitive.length, distance+speed*step/2))
                middle_speed, _ = course_kinematics(midpoint.heading, primitive.curvature, self.wind, airspeed)
                step = min(step, (primitive.length-distance)/middle_speed)
                distance = min(primitive.length, distance+middle_speed*step)
                stamp += step
                if len(rows) > 60000:
                    raise ValueError("path exceeds bounded planner sample count")
        end = self.path[-1].end
        speed, bank = course_kinematics(end.heading, self.path[-1].curvature, self.wind, airspeed)
        rows.append((stamp, end.x, end.y, end.heading, speed, bank))
        self.samples = np.array(rows)
        self.samples[:, 3] = np.unwrap(self.samples[:, 3])
        self.samples.flags.writeable = False
        self.duration = stamp

    @classmethod
    def from_samples(cls, rows, wind, airspeed=18.):
        samples = np.asarray(rows, dtype=float)
        if (samples.ndim != 2 or samples.shape[1] != 6 or not 2 <= len(samples) <= 16000
                or not np.isfinite(samples).all() or abs(samples[0,0]) > 1e-8
                or not np.all(np.diff(samples[:,0]) > 0)):
            raise ValueError("bounded finite strictly timed samples required")
        result = object.__new__(cls)
        result.samples = samples.copy()
        result.samples[:,3] = np.unwrap(result.samples[:,3])
        result.samples.flags.writeable = False
        result.wind = np.asarray(wind,dtype=float).copy()
        if result.wind.shape != (2,) or not np.isfinite(result.wind).all():
            raise ValueError("finite planar wind required")
        result.airspeed = airspeed
        result.duration = float(samples[-1,0])
        result.path = ()
        return result

    @classmethod
    def concatenate(cls, paths):
        paths = tuple(paths)
        if not paths:
            raise ValueError("nonempty path sequence required")
        rows, stamp = [], 0.
        for i,p in enumerate(paths):
            if not np.array_equal(p.wind,paths[0].wind):
                raise ValueError("concatenated paths require the same wind")
            if i:
                a,b = paths[i-1].at(paths[i-1].duration),p.at(0)
                if np.linalg.norm(a[:2]-b[:2]) > 1e-5 or abs(wrap_angle(a[2]-b[2])) > 1e-5:
                    raise ValueError("continuous concatenation required")
            part = p.samples.copy()
            part[:,0] += stamp
            rows.extend(part[:-1])
            stamp += p.duration
        rows.append(part[-1])
        return cls.from_samples(rows,paths[0].wind,paths[0].airspeed)

    def slice(self, start, finish):
        if not 0 <= start < finish <= self.duration:
            raise ValueError("finite increasing slice inside path required")
        # Avoid duplicate boundary stamps caused by repeated0.05 additions.
        # Keeping a point~1e-15s beside the exact boundary would turn harmless
        # roundoff into an enormous implied interpolation speed.
        middle = self.samples[(self.samples[:,0] > start+1e-8) & (self.samples[:,0] < finish-1e-8)]
        rows = np.vstack((np.r_[start,self.at(start)],middle,np.r_[finish,self.at(finish)]))
        rows[:,0] -= start
        return self.from_samples(rows,self.wind,self.airspeed)

    def at(self, elapsed):
        if not math.isfinite(elapsed) or not 0 <= elapsed <= self.duration+1e-6:
            raise ValueError("path time outside committed interval")
        times = self.samples[:, 0]
        i = max(0, min(len(times)-2, int(np.searchsorted(times, elapsed, side="right")-1)))
        fraction = float(np.clip((elapsed-times[i])/(times[i+1]-times[i]), 0., 1.))
        return self.samples[i, 1:]*(1-fraction)+self.samples[i+1, 1:]*fraction

    def target(self, elapsed, position, altitude):
        return tracking_target(self.at(elapsed), position, altitude, self.wind)


def tracking_target(sample, position, altitude, wind):
    x, y, heading, speed, bank = sample
    tangent = np.array([math.cos(heading), math.sin(heading)])
    correction = .7*(np.array([x, y])-np.asarray(position)[:2])
    magnitude = float(np.linalg.norm(correction))
    if magnitude > 4:
        correction *= 4/magnitude
    ground_velocity = speed*tangent+correction
    requested_airspeed = float(np.clip(np.linalg.norm(ground_velocity-wind), 16., 24.))
    return FlightTarget(math.atan2(ground_velocity[1], ground_velocity[0]), altitude, requested_airspeed, bank)


@dataclass(frozen=True)
class RouteProgram:
    """Finite prefix with a target-independent periodic physical holding tail."""

    prefix: TimedPath
    tail: TimedPath

    def __post_init__(self):
        a, b = self.prefix.at(self.prefix.duration), self.tail.at(0)
        end = self.tail.at(self.tail.duration)
        if (np.linalg.norm(a[:2]-b[:2]) > 1e-5 or abs(wrap_angle(a[2]-b[2])) > 1e-5
                or np.linalg.norm(end[:2]-b[:2]) > 1e-5 or abs(wrap_angle(end[2]-b[2])) > 1e-5
                or not np.array_equal(self.prefix.wind, self.tail.wind)):
            raise ValueError("continuous prefix and closed periodic tail required")

    def at(self, elapsed):
        if not math.isfinite(elapsed) or elapsed < 0:
            raise ValueError("causal program time required")
        if elapsed < self.prefix.duration:
            return self.prefix.at(elapsed)
        return self.tail.at((elapsed-self.prefix.duration) % self.tail.duration)

    def target(self, elapsed, position, altitude):
        return tracking_target(self.at(elapsed), position, altitude, self.prefix.wind)


def fleet_clearance(programs, *, sample_dt=.05):
    if len(programs) != 4 or not math.isfinite(sample_dt) or sample_dt <= 0:
        raise ValueError("exactly four programs and positive sampling interval required")
    for p in programs:
        for path in (p.prefix,p.tail):
            slope = np.linalg.norm(np.diff(path.samples[:,1:3],axis=0),axis=1)/np.diff(path.samples[:,0])
            if not np.isfinite(slope).all() or float(slope.max()) > 27+1e-6:
                raise ValueError("nominal interpolated path exceeds27m/s Lipschitz premise")
    period = programs[0].tail.duration
    if any(abs(p.tail.duration-period) > 1e-6 for p in programs):
        raise ValueError("different tail periods need a different infinite-tail proof")
    # Once all have reached equal-period tails, their joint geometry repeats.
    end = max(p.prefix.duration for p in programs)+period
    times = np.r_[np.arange(0., end, sample_dt), end]
    positions = [np.array([p.at(float(t))[:2] for t in times]) for p in programs]
    minimum = min(float(np.linalg.norm(positions[i]-positions[j], axis=1).min())
                  for i in range(4) for j in range(i+1, 4))
    maximum = max(float(np.abs(p).max()) for p in positions)
    return {"sampled_minimum_horizontal_m": minimum, "continuous_lower_bound_horizontal_m": minimum-27*sample_dt,
            "maximum_abs_xy_m_sampled": maximum, "continuous_abs_xy_upper_bound_m": maximum+13.5*sample_dt,
            "checked_seconds": end, "joint_periodic_tail_seconds": period,
            "scope": "complete ideal nominal prefix+periodic-tail geometry; no physical tracking certificate"}

"""Task tools and evaluator-owned evidence. Responses contain no truth verdict."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
import math
from typing import Callable

from envs.inspection.scoring import GradingMeasurement


def audit_value(value):
    if isinstance(value, float) and not math.isfinite(value):
        return {"invalid_numeric": repr(value)}
    if isinstance(value, dict):
        return {str(k): audit_value(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [audit_value(v) for v in value]
    return value


@dataclass(frozen=True)
class Observation:
    evidence_id: str
    candidate_id: str
    drone_id: int
    measured_at: float
    arrived_at: float
    estimate_xy: tuple[float, float]
    estimated_class: str
    object_type: str
    quality: float
    covariance_xy: tuple[float, float]
    sensor_mode: str
    aircraft_xy: tuple[float, float]
    camera_xyz: tuple[float, float, float] | None = None

    def public(self):
        return asdict(self)


@dataclass(frozen=True)
class Evidence:
    observation: Observation
    entity_key: str | None  # evaluator-only; never serialized to actor


@dataclass
class Report:
    report_id: str
    object_type: str
    associated_key: str | None
    created_at: float
    versions: list[GradingMeasurement] = field(default_factory=list)
    withdrawn: bool = False


class ReportLedger:
    def __init__(self, budget: int, classes: set[str], truth_at: Callable):
        self.budget, self.classes, self.truth_at = budget, classes, truth_at
        self.evidence: dict[str, Evidence] = {}
        self.reports: dict[str, Report] = {}
        self.audit = []
        self.association_ambiguities = 0

    def register(self, evidence: Evidence):
        key = evidence.observation.evidence_id
        if key in self.evidence and self.evidence[key] != evidence:
            raise ValueError("minted evidence is immutable")
        self.evidence[key] = evidence

    def submit(self, request: dict, now: float) -> dict:
        required = {"report_id", "object_type", "candidate_id", "measured_at", "estimate_xy", "claimed_class", "evidence_ids"}
        try:
            if set(request) != required:
                raise ValueError("report schema fields do not match")
            report_id = request["report_id"]
            if not isinstance(report_id, str) or not 1 <= len(report_id) <= 64:
                raise ValueError("invalid report ID")
            if request["object_type"] not in ("static", "dynamic") or request["claimed_class"] not in self.classes:
                raise ValueError("unknown object type or class")
            if not isinstance(request["candidate_id"], str):
                raise ValueError("candidate handle must be a string")
            xy, stamp = request["estimate_xy"], request["measured_at"]
            if not isinstance(xy, (list, tuple)) or len(xy) != 2:
                raise ValueError("planar estimate required")
            if any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in (*xy, stamp)):
                raise ValueError("finite numerical estimate and time required")
            ids = request["evidence_ids"]
            if not isinstance(ids, list) or any(not isinstance(i, str) for i in ids) or len(ids) != len(set(ids)):
                raise ValueError("evidence IDs must be a unique string list")
            existing = self.reports.get(report_id)
            if existing and existing.object_type != request["object_type"]:
                raise ValueError("a report cannot change object type")
            if not existing and len(self.reports) >= self.budget:
                raise ValueError("report capacity exhausted")
        except (ValueError, TypeError) as error:
            response = {"status": "rejected", "reason": str(error)}
            self.audit.append(audit_value({"t": now, "request": request, "response": response}))
            return response
        references = [self.evidence[i] for i in ids if i in self.evidence]
        causal = (bool(ids) and len(references) == len(ids) and 0 <= stamp <= now
                  and all(e.observation.measured_at <= stamp and e.observation.arrived_at <= now for e in references)
                  and any(e.observation.measured_at == stamp for e in references))
        if existing is None:
            occupied = {r.associated_key for r in self.reports.values() if r.associated_key is not None}
            matches = []
            if 0 <= stamp <= now:
                for key, position in self.truth_at(stamp).items():
                    distance = math.hypot(xy[0]-position[0], xy[1]-position[1])
                    if distance <= 20 and key not in occupied:
                        matches.append((distance, key))
            matches.sort()
            self.association_ambiguities += int(len(matches) > 1)
            existing = Report(report_id, request["object_type"], matches[0][1] if matches else None, now)
            self.reports[report_id] = existing
        identity_correct = (existing.associated_key is not None and bool(references)
                            and all(e.entity_key == existing.associated_key
                                    and e.observation.candidate_id == request["candidate_id"] for e in references))
        quality_valid = bool(references) and all(e.observation.quality >= .8 for e in references)
        # An invalid/future claim consumes capacity but cannot enter a score.
        safe_stamp = max(0.0, min(float(stamp), now))
        new_evidence_ids = sorted(e.observation.evidence_id for e in references if e.observation.measured_at == stamp)
        measurement_id = new_evidence_ids[0] if new_evidence_ids else "unsupported-"+str(len(existing.versions))
        version = GradingMeasurement(measurement_id, safe_stamp, now, tuple(xy), request["claimed_class"],
                                     identity_correct, quality_valid, causal, len(existing.versions)+1)
        if existing.object_type == "dynamic":
            previous = next((v for v in existing.versions if v.evidence_id == measurement_id), None)
            if previous is not None:
                same = (previous.measured_at == version.measured_at and previous.estimate_xy == version.estimate_xy
                        and previous.claimed_class == version.claimed_class)
                response = {"status": "accepted" if same else "rejected", "report_id": report_id,
                            "reason": "idempotent frozen measurement" if same else "dynamic measurements are sealed"}
                self.audit.append(audit_value({"t": now, "request": request, "response": response}))
                return response
        existing.versions.append(version)
        existing.withdrawn = False
        response = {"status": "accepted", "report_id": report_id,
                    "slots_used": len(self.reports), "slots_remaining": self.budget-len(self.reports)}
        self.audit.append(audit_value({"t": now, "request": request, "response": response}))
        return response

    def withdraw(self, report_id):
        if report_id not in self.reports:
            return {"status": "rejected", "reason": "unknown report"}
        self.reports[report_id].withdrawn = True
        return {"status": "accepted", "slots_used": len(self.reports)}


@dataclass
class Job:
    job_id: str
    drone_id: int
    kind: str
    version: int
    created_at: float
    params: dict
    status: str = "queued"
    started_at: float | None = None
    finished_at: float | None = None
    reason: str | None = None


class JobBook:
    def __init__(self, count):
        self.versions = [0]*count
        self.jobs: dict[str, Job] = {}
        self.active: dict[int, str] = {}
        self.transitions = []

    def create(self, drone_id, kind, params, expected_version, now, *, preempt=False):
        if isinstance(drone_id, bool) or not isinstance(drone_id, int) or not 0 <= drone_id < len(self.versions):
            return {"status": "rejected", "reason": "unknown aircraft"}
        if isinstance(expected_version, bool) or not isinstance(expected_version, int) or expected_version != self.versions[drone_id]:
            return {"status": "rejected", "reason": "stale version", "version": self.versions[drone_id]}
        if drone_id in self.active:
            old = self.jobs[self.active[drone_id]]
            if old.status in ("queued", "running"):
                if not preempt:
                    return {"status": "rejected", "reason": "aircraft has an active job"}
                self.transition(old, "cancelled", now, "preempted by safe exit")
        self.versions[drone_id] += 1
        job_id = f"job-{len(self.jobs)+1:04d}"
        job = Job(job_id, drone_id, kind, self.versions[drone_id], now, dict(params))
        self.jobs[job_id] = job
        self.active[drone_id] = job_id
        self.transitions.append({"t": now, "job_id": job_id, "status": "queued"})
        return {"status": "accepted", "job_id": job_id, "version": job.version}

    def transition(self, job, status, now, reason=None):
        legal = {"queued": {"running", "cancelled", "failed"},
                 "running": {"succeeded", "failed", "cancelled"}}
        if status not in legal.get(job.status, set()):
            raise ValueError("illegal job state transition")
        job.status, job.reason = status, reason
        if status == "running":
            job.started_at = now
        else:
            job.finished_at = now
        self.transitions.append({"t": now, "job_id": job.job_id, "status": status, "reason": reason})

    def cancel(self, job_id, expected_version, now):
        job = self.jobs.get(job_id)
        if job is None:
            return {"status": "rejected", "reason": "unknown job"}
        if expected_version != self.versions[job.drone_id] or isinstance(expected_version, bool) or not isinstance(expected_version, int):
            return {"status": "rejected", "reason": "stale version"}
        if job.status not in ("queued", "running"):
            return {"status": "rejected", "reason": "job already terminal"}
        self.transition(job, "cancelled", now, "actor cancellation")
        self.versions[job.drone_id] += 1
        return {"status": "accepted", "version": self.versions[job.drone_id]}

    def public(self):
        return [asdict(job) for job in self.jobs.values()]

"""B0 reference policy. Input is exclusively the serialized public stream."""

from __future__ import annotations

from collections import Counter, defaultdict
import math


class ReferencePolicy:
    def __init__(self):
        self.history = defaultdict(list)
        self.seen = set()
        self.reports = {}
        self.report_points = {}
        self.pending_reports = {}
        self.report_aliases = defaultdict(set)
        self.rejected = set()
        self.observed = set()
        self.confirmed = set()
        self.pending = set()
        self.pending_cancellations = {}
        self.calls = 0

    def result(self, name, args, response):
        if "drone_id" in args:
            self.pending.discard(args["drone_id"])
        elif name == "cancel_job" and args["job_id"] in self.pending_cancellations:
            self.pending.discard(self.pending_cancellations.pop(args["job_id"]))
        if name == "submit_or_revise_report":
            rid = args["report_id"]
            self.pending_reports.pop(rid,None)
            aliases = self.report_aliases.pop(rid,set())
            if response.get("status") == "accepted":
                for candidate in aliases:
                    self.reports[candidate] = rid
        if response.get("status") != "accepted":
            return
        if name == "submit_or_revise_report":
            self.reports[args["candidate_id"]] = args["report_id"]
            self.report_points[args["report_id"]] = {"xy":args["estimate_xy"],"object_type":args["object_type"],
                                                   "claimed_class":args["claimed_class"]}
        elif name == "observe_track":
            self.observed.add(args["candidate_id"])

    @staticmethod
    def report_request(obs):
        return {"report_id": "report-"+obs["candidate_id"], "object_type": obs["object_type"],
                "candidate_id": obs["candidate_id"], "measured_at": obs["measured_at"],
                "estimate_xy": obs["estimate_xy"], "claimed_class": obs["estimated_class"],
                "evidence_ids": [obs["evidence_id"]]}

    def decide(self, state):
        for obs in state["observations"]:
            if obs["evidence_id"] not in self.seen:
                self.seen.add(obs["evidence_id"])
                self.history[obs["candidate_id"]].append(obs)
        jobs = state["jobs"]
        for job in jobs:
            candidate = job["params"].get("candidate_id")
            if job["kind"] == "inspect" and job["status"] == "succeeded":
                self.confirmed.add(candidate)
            if job["kind"] == "inspect" and job["status"] == "failed" and candidate not in self.reports:
                self.rejected.add(candidate)
            if job["kind"] == "observe" and job["status"] in ("failed","cancelled"):
                self.observed.discard(candidate)
        commands = []
        for candidate, observations in self.history.items():
            qualified = [o for o in observations if o["sensor_mode"] == "inspect" and o["quality"] >= .8]
            if len(qualified) >= 2 and any(math.dist(qualified[0]["aircraft_xy"], o["aircraft_xy"]) >= 20 for o in qualified[1:]):
                counts = Counter(o["estimated_class"] for o in qualified[-8:])
                winner,count = counts.most_common(1)[0]
                if count <= sum(counts.values())/2:
                    continue
                latest = next(o for o in reversed(qualified) if o["estimated_class"] == winner)
                if winner == "normal":
                    self.rejected.add(candidate)
                elif (candidate not in self.reports and state["report_slots_used"]+len(self.pending_reports)
                      < state["task_card"]["report_budget"]):
                    # Per-aircraft handles are not global identities. Merge
                    # independently confirmed static locations from public
                    # measurements before consuming another report slot.
                    duplicate = next((rid for rid,row in {**self.report_points,**self.pending_reports}.items()
                                      if latest["object_type"] == row["object_type"] == "static"
                                      and math.dist(latest["estimate_xy"],row["xy"]) <= 15),None)
                    if duplicate is not None:
                        if duplicate in self.report_points:
                            self.reports[candidate] = duplicate
                        else:
                            self.report_aliases[duplicate].add(candidate)
                    else:
                        report = self.report_request(latest)
                        self.pending_reports[report["report_id"]] = {"xy":report["estimate_xy"],"object_type":report["object_type"],
                                                                   "claimed_class":report["claimed_class"]}
                        commands.append(("submit_or_revise_report", report))
        for aircraft in state["aircraft"]:
            i = aircraft["drone_id"]
            if i in self.pending or aircraft["retired"] or not aircraft["link_available"]:
                continue
            active = next((j for j in reversed(jobs) if j["drone_id"] == i and j["status"] in ("queued", "running")), None)
            version = aircraft["job_version"]
            if state["sim_time"] >= 470:
                if not active or active["kind"] != "exit":
                    # A terminal exit keeps its physical orbit without reissuing.
                    if any(j["drone_id"] == i and j["kind"] == "exit" and j["status"] == "succeeded" for j in jobs):
                        continue
                    commands.append(("enter_safe_exit", {"drone_id": i, "expected_version": version}))
                    self.pending.add(i)
                continue
            if active and active["kind"] in ("inspect", "observe", "exit"):
                continue
            candidates = []
            for candidate, observations in self.history.items():
                latest = observations[-1]
                if candidate in self.rejected or len(observations) < 2 or latest["estimated_class"] == "normal":
                    continue
                if candidate in self.confirmed and candidate not in self.reports:
                    # Completion telemetry may precede the last camera packet.
                    # Wait for that evidence instead of starting a second job.
                    continue
                if latest["drone_id"] != i or state["sim_time"]-latest["measured_at"] > 30:
                    continue
                if candidate in self.reports:
                    if latest["object_type"] != "dynamic" or candidate in self.observed:
                        continue
                candidates.append((latest["measured_at"], candidate, latest))
            selected = max(candidates, default=None)
            if selected and aircraft["camera_quality"] >= .8:
                if active:
                    commands.append(("cancel_job", {"job_id": active["job_id"], "expected_version": version}))
                    self.pending_cancellations[active["job_id"]] = i
                else:
                    _, candidate, latest = selected
                    rule = "dynamic-inspection" if latest["object_type"] == "dynamic" else next(
                        r["rule_id"] for r in state["task_card"]["rules"] if latest["estimated_class"] in r["classes"])
                    args = {"drone_id": i, "candidate_id": candidate, "expected_version": version,
                            "rule_id": rule, "task_card_version": state["task_card"]["task_card_version"]}
                    if candidate in self.reports:
                        args.update(duration=min(180.0, 470-state["sim_time"]), report_id=self.reports[candidate])
                        commands.append(("observe_track", args))
                    else:
                        commands.append(("inspect_candidate", args))
                self.pending.add(i)
            elif not active:
                commands.append(("assign_survey", {"drone_id": i, "region_id": f"stripe-{i}", "duration": 100.0,
                                                   "expected_version": version, "rule_id": "static-0",
                                                   "task_card_version": state["task_card"]["task_card_version"]}))
                self.pending.add(i)
        self.calls += len(commands)
        return commands
